function set_option_int!(obj::wxImage, name::AbstractString, value::Integer)
    name_ws = wxString(name)
    try
        KwxFFI.wxImage_SetOptionInt(obj.ptr, name_ws.ptr, Cint(value))
    finally
        Base.delete!(name_ws)
    end
    nothing
end

function set_rgb!(obj::wxImage, x::Integer, y::Integer, r::Integer, g::Integer, b::Integer)
    KwxFFI.wxImage_SetRGB(obj.ptr, Cint(x), Cint(y), Cuchar(r), Cuchar(g), Cuchar(b))
    nothing
end

